import re

from ._emoji_codes import EMOJI


def _emoji_replace(text: str, _emoji_sub=re.compile(r"(:(\S*?):)").sub, custom_emoji: Optional[Dict[str, str]] = None) -> str:
    """Replace emoji code in text."""
    # Create a combined emoji dictionary
    emoji_dict = EMOJI.copy()
    if custom_emoji:
        emoji_dict.update(custom_emoji)

    get_emoji = emoji_dict.get

    def do_replace(match: Match[str]) -> str:
        """Called by re.sub to do the replacement."""
        emoji_code, emoji_name = match.groups()
        return get_emoji(emoji_name.lower(), emoji_code)

    return _emoji_sub(do_replace, text)"}

